using HakutaiKagami.Core.Contracts;
using HakutaiKagami.Core.Messaging;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class CommunityStewardshipTests
{
    static readonly EntityId Site=new("site:kofu"),Head=new("person:shingen"),Agent=HistoricalHouseholdCatalog.Edition.People.Single().Id;
    internal static WorldSession Start(bool employee=false)=>new(NewGameWorld.Create(NewGameWorld.Scenario(HistoricalStartCatalog.Current),[],employee?Agent.Value:Head.Value,1,historicalCatalog:HistoricalStartCatalog.Current,inspectionPolicy:LocalInspectionFindings.Policy,workPolicy:WorkFollowup.Policy,economyPolicy:CommunityStewardship.Policy));
    static CommandResult Act(WorldSession s,StewardAction a,EntityId? g=null,EconomyAction? op=null,long n=0,string? report=null,string? id=null,EntityId? address=null,int days=30)=>s.ManageStewardship(new(new(id??"request:steward/"+s.Revision),a,Site,s.PlayerControl==Head?Agent:Head,g,op,n,days,address??Site,report),s.PlayerControl,s.Revision);
    static void Good(CommandResult r)=>Assert.True(r.Code==ResultCode.Accepted,r.VisibleReason);
    static EntityId Grant(WorldSession s,EntityId? address=null,int days=30){Good(Act(s,StewardAction.Assign,address:address,days:days));return s.DiagnosticSnapshot().Stewardship!.Grants.Last().Id;}
    static void Advance(WorldSession s,long at){while(s.Seconds<at){long old=s.Seconds;s.SetPaused(false);s.AdvanceTo(at,100000);Assert.True(s.Seconds>old);}}
    static CommunityAccounts A(WorldSession s)=>s.DiagnosticSnapshot().Communities!.Accounts.Single(a=>a.Site==Site);
    static void OpenAll(WorldSession s){foreach(var m in s.DiagnosticSnapshot().Messaging.Messages.Where(m=>m.RecipientId==s.PlayerControl.Value&&s.DiagnosticSnapshot().Messaging.Attempts.Any(a=>a.MessageId==m.Id&&a.Status==AttemptStatus.Delivered)).ToArray())s.Open(s.PlayerControl,new(m.Id),s.Revision);}
    [Theory][InlineData(false)][InlineData(true)]public void LocalMutualScopeDoesNotTransferRolesTroopsOrOwnership(bool employee){var s=Start(employee);var w=s.DiagnosticSnapshot();Assert.Equal(!employee,s.VillageView()!.CanPromise);Grant(s);var after=s.DiagnosticSnapshot();Assert.Equal(ContractJson.Write(w.Offices),ContractJson.Write(after.Offices));Assert.Equal(ContractJson.Write(w.ServiceBonds),ContractJson.Write(after.ServiceBonds));Assert.Equal(ContractJson.Write(w.LandRights),ContractJson.Write(after.LandRights));Assert.Equal(ContractJson.Write(w.Units),ContractJson.Write(after.Units));Assert.Equal(3000,A(s).HouseRice);}
    [Fact]public void NpcDelegateUsesRealLocalLaborWhenPrincipalLeaves(){var s=Start();Grant(s,new("site:castle"));Good(s.Submit(TravelWorld.Move(s.DiagnosticSnapshot(),"request:head-trip","castle"),s.Revision));Advance(s,86400);Assert.Equal(2800,A(s).HouseRice);Assert.Equal(20,A(s).Reserved);Assert.Contains(s.DiagnosticSnapshot().CommunityAdministration!.Decisions,d=>d.Site==Site&&d.Actor==Agent&&d.Action==EconomyAction.ImproveWater);Assert.Empty(s.StewardshipView()!.Reports);}
    [Fact]public void PlayerDelegateIsNeverAutoplayed(){var s=Start(true);Grant(s);Advance(s,86400);Assert.Equal(3000,A(s).HouseRice);Assert.DoesNotContain(s.DiagnosticSnapshot().CommunityAdministration!.Decisions,d=>d.Actor==s.PlayerControl);}
    [Fact]public void ActualDelegateReliefIsBoundedPerMonthAndNotPerButton(){var s=Start(true);var g=Grant(s);Good(Act(s,StewardAction.Operate,g,EconomyAction.RelieveVillage,300));Good(Act(s,StewardAction.Operate,g,EconomyAction.RelieveVillage,200));var before=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,Act(s,StewardAction.Operate,g,EconomyAction.RelieveVillage,1).Code);Assert.Equal(before,ContractJson.Write(s.DiagnosticSnapshot()));Assert.Equal(2500,A(s).HouseRice);}
    [Fact]public void DelegateCannotBypassBudgetThroughLegacyCommunityButton(){var s=Start(true);var g=Grant(s);Good(Act(s,StewardAction.Operate,g,EconomyAction.RelieveVillage,500));Assert.Equal(ResultCode.NotAvailable,s.ManageCommunity(new(new("request:bypass-grant"),Site,EconomyAction.RelieveVillage,1),s.PlayerControl,s.Revision).Code);}
    [Fact]public void WaterNeedsGrantConditionsAndActualCompletion(){var s=Start(true);var g=Grant(s);Good(Act(s,StewardAction.Operate,g,EconomyAction.ImproveWater,200));Assert.Equal(20,A(s).Reserved);Advance(s,7*86400);Assert.Equal(110,A(s).Water);Assert.Equal(ResultCode.NotAvailable,Act(s,StewardAction.Operate,g,EconomyAction.ImproveWater,200).Code);}
    [Fact]public void GrantExpiryIsExclusiveAndCannotLeaveFutureAuthority(){var s=Start(true);var g=Grant(s,days:1);Advance(s,86400-1);Good(Act(s,StewardAction.Operate,g,EconomyAction.RelieveVillage,1));Advance(s,86400);Assert.False(s.StewardshipView()!.Grants.Single().CanOperate);Assert.Equal(ResultCode.NotAvailable,Act(s,StewardAction.Operate,g,EconomyAction.RelieveVillage,1).Code);}
    [Fact]public void AnotherActiveGrantCannotOverlapSameSite(){var s=Start();Grant(s);Assert.Equal(ResultCode.NotAvailable,Act(s,StewardAction.Assign).Code);}
    [Fact]public void NoGrantMeansNoEmployeeAccessToHouseAccounts(){var s=Start(true);Assert.Null(s.CommunityEconomyView());Assert.Equal(ResultCode.NotAvailable,Act(s,StewardAction.Operate,new("request:fake-grant"),EconomyAction.RelieveVillage,1).Code);Grant(s);Assert.NotNull(s.CommunityEconomyView());}
    [Fact]public void ReportTransitDoesNotRevealObservationBeforeOpening(){var s=Start();Grant(s);Advance(s,86400);var report=s.DiagnosticSnapshot().Stewardship!.Papers.Single(p=>p.Kind==CommunityStewardship.ReportKind);Assert.Empty(s.StewardshipView()!.Reports);Advance(s,86410);Assert.Empty(s.StewardshipView()!.Reports);Good(s.Open(Head,new(report.Id),s.Revision));var known=Assert.Single(s.StewardshipView()!.Reports);Assert.Equal(86400,known.Observation!.ObservedAt);Assert.Equal(2800,known.Observation.Accounts.HouseRice);}
    [Fact]public void KnownReportRemainsOldAfterFurtherSpending(){var s=Start();Grant(s);Advance(s,86410);OpenAll(s);var report=s.StewardshipView()!.Reports.Single();Good(s.ManageCommunity(new(new("request:own-head-relief"),Site,EconomyAction.RelieveVillage,500),s.PlayerControl,s.Revision));Assert.Equal(2300,A(s).HouseRice);Assert.Equal(2800,s.StewardshipView()!.Reports.Single().Observation!.Accounts.HouseRice);Assert.Equal(report,s.StewardshipView()!.Reports.Single());}
    [Fact]public void ReportResendCopiesSameObservationWithoutNewRiceMovement(){var s=Start(true);var g=Grant(s);Good(Act(s,StewardAction.Report,g));var report=s.DiagnosticSnapshot().Stewardship!.Papers.Single();Good(Act(s,StewardAction.Operate,g,EconomyAction.RelieveVillage,100));Good(Act(s,StewardAction.ResendReport,g,report:report.Id));var resend=s.DiagnosticSnapshot().Stewardship!.Papers.Last();Assert.Equal(report.Observation,resend.Observation);Assert.Equal(report.Id,resend.Original);Assert.Equal(2900,A(s).HouseRice);Assert.Equal(3000,resend.Observation!.Accounts.HouseRice);}
    [Fact]public void RevocationSendReceiptAndPrincipalsKnowledgeAreSeparate(){var s=Start();var g=Grant(s);Good(Act(s,StewardAction.Revoke,g));Assert.Empty(s.DiagnosticSnapshot().Stewardship!.Receipts);Assert.Contains("未確認",s.StewardshipView()!.Grants.Single().Status);Advance(s,2);Assert.Single(s.DiagnosticSnapshot().Stewardship!.Receipts);Assert.Contains("未確認",s.StewardshipView()!.Grants.Single().Status);Advance(s,5);OpenAll(s);Assert.Contains("返報を確認",s.StewardshipView()!.Grants.Single().Status);Advance(s,86400);Assert.Equal(3000,A(s).HouseRice);}
    [Fact]public void AgentCannotRevokePrincipalsGrantByImpersonation(){var s=Start(true);var g=Grant(s);Assert.Equal(ResultCode.NotAvailable,Act(s,StewardAction.Revoke,g).Code);}
    [Fact]public void UnrelatedOrRemotePersonCannotBecomeDelegate(){var s=Start();var w=s.DiagnosticSnapshot();Assert.Equal(ResultCode.NotAvailable,s.ManageStewardship(new(new("request:foreign-agent"),StewardAction.Assign,Site,new("person:ujiyasu"),ReturnAddress:Site),Head,s.Revision).Code);Assert.Equal(ContractJson.Write(w),ContractJson.Write(s.DiagnosticSnapshot()));}
    [Theory][InlineData(0)][InlineData(31)]public void GrantDaysMustBeBounded(int days){var s=Start();Assert.Equal(ResultCode.NotAvailable,Act(s,StewardAction.Assign,days:days).Code);}
    [Fact]public void StaleAndDuplicateCommandsCannotSpendTwice(){var s=Start(true);var g=Grant(s);long r=s.Revision;Good(Act(s,StewardAction.Operate,g,EconomyAction.RelieveVillage,100,id:"request:once"));Assert.Equal(ResultCode.AlreadyAccepted,Act(s,StewardAction.Operate,g,EconomyAction.RelieveVillage,100,id:"request:once").Code);Assert.Equal(ResultCode.IdPayloadConflict,Act(s,StewardAction.Operate,g,EconomyAction.RelieveVillage,101,id:"request:once").Code);Assert.Equal(ResultCode.StateChanged,s.ManageStewardship(new(new("request:stale"),StewardAction.Report,Site,Grant:g),s.PlayerControl,r).Code);Assert.Equal(2900,A(s).HouseRice);}
    [Fact]public void OldV6WorldBytesRemainIndependent(){var s=NpcCommunityAdministrationTests.Start();var bytes=ContractJson.Write(s.DiagnosticSnapshot());Assert.DoesNotContain("Stewardship",System.Text.Encoding.UTF8.GetString(bytes));Assert.Equal(bytes,ContractJson.Write(new WorldSession(ContractJson.Read<ContractWorld>(bytes)).DiagnosticSnapshot()));var w=s.DiagnosticSnapshot();w.Stewardship=Start().DiagnosticSnapshot().Stewardship;Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Fact]public void ForgedGrantOrObservationCannotLoad(){var s=Start(true);var g=Grant(s);Good(Act(s,StewardAction.Report,g));var w=s.DiagnosticSnapshot();w.Stewardship=w.Stewardship! with{Grants=[w.Stewardship.Grants.Single() with{Until=99999999}]};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));w=s.DiagnosticSnapshot();var p=w.Stewardship!.Papers.Single();w.Stewardship=w.Stewardship with{Papers=[p with{Observation=p.Observation! with{Accounts=p.Observation.Accounts with{HouseRice=9999}}}]};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Fact]public void MainEntryProfileContainsExplicitStewardshipOnlyInNewVersion(){var store=new NewCampaignStore(Path.Combine(Path.GetTempPath(),"steward-profile-"+Guid.NewGuid().ToString("N")));var p=store.New(NewGameWorld.Scenario(HistoricalStartCatalog.Current),[],Head.Value,1,NewGameWorld.CompactPersonalAuthority,HistoricalStartCatalog.Current,NewGameNpcRoutine.Policy,LocalInspectionFindings.Policy,WorkFollowup.Policy,null,VoyageExpense.Standard,NpcArmies.CompactCombatPolicy,CommunityStewardship.Policy,PersonalCompanions.RetainerReleasePolicy,TruceNegotiations.Policy,PrivateInformation.Policy,PrivateStanddown.Policy);var s=new WorldSession(NewCampaignStore.Build(store.Read(p.Instance)));Assert.NotNull(s.StewardshipView());Assert.Contains(Agent,s.StewardshipView()!.People);}
    [Theory][InlineData(0)][InlineData(1)][InlineData(2)][InlineData(3)][InlineData(4)]public void ActualGenerationRecoveryOfTravelReportRevocationAndOperationPreservesFuture(int phase){bool employee=phase is 1 or 4;var a=Start(employee);var g=Grant(a);if(phase==0){Good(a.Submit(TravelWorld.Move(a.DiagnosticSnapshot(),"request:recovery-travel","castle"),a.Revision));Advance(a,2);}if(phase==1)Good(Act(a,StewardAction.Report,g));if(phase is 2 or 3){Good(Act(a,StewardAction.Revoke,g));if(phase==3)Advance(a,2);}if(phase==4)Good(Act(a,StewardAction.Operate,g,EconomyAction.ImproveWater,200));a.SetPaused(true);var w=a.DiagnosticSnapshot();var store=new GenerationSaveStore(Path.Combine(Path.GetTempPath(),"steward-"+Guid.NewGuid().ToString("N")),w.Definitions);Assert.True(store.Save(a,"steward",w.WorldId).Published);var host=new WorldSessionHost(Start(employee));Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("steward"),host.Current,host.Current.Revision));var b=host.Current;Assert.Equal(ContractJson.Write(a.StewardshipView()),ContractJson.Write(b.StewardshipView()));var dir=Environment.GetEnvironmentVariable("HAKUTAI_WORLD_CLASH_QA_DIR");if(!string.IsNullOrEmpty(dir)){Directory.CreateDirectory(dir);File.WriteAllBytes(Path.Combine(dir,"steward-"+phase+".before.json"),ContractJson.Write(a.DiagnosticSnapshot()));File.WriteAllBytes(Path.Combine(dir,"steward-"+phase+".restored.json"),ContractJson.Write(b.DiagnosticSnapshot()));}Advance(a,a.Seconds+8*86400);Advance(b,b.Seconds+8*86400);OpenAll(a);OpenAll(b);Assert.Equal(ContractJson.Write(a.DiagnosticSnapshot()),ContractJson.Write(b.DiagnosticSnapshot()));Assert.Equal(ContractJson.Write(a.StewardshipView()),ContractJson.Write(b.StewardshipView()));}

    [Fact]public void ReportTravelsToTheAgreedSiteAndIsNotCurrentWorldTruth(){var s=Start();Grant(s,new("site:castle"));Good(s.Submit(TravelWorld.Move(s.DiagnosticSnapshot(),"request:report-trip","castle"),s.Revision));Advance(s,2);long arrival=s.DiagnosticSnapshot().Branches!.Journeys.Last(j=>j.Actor==Head).Legs[^1].EndAt;Advance(s,arrival+5*86400);var p=s.DiagnosticSnapshot().Stewardship!.Papers.First(p=>p.Kind==CommunityStewardship.ReportKind);Assert.Equal(new EntityId("site:castle"),p.Address);var delivered=s.DiagnosticSnapshot().Stewardship!.Papers.Single(q=>q.Kind==CommunityStewardship.ReportKind&&s.DiagnosticSnapshot().Messaging.Attempts.Any(a=>a.MessageId==q.Id&&a.Status==AttemptStatus.Delivered));Assert.NotNull(delivered.Original);Assert.Equal(p.Observation,delivered.Observation);Good(s.Open(Head,new(delivered.Id),s.Revision));Assert.True(s.StewardshipView()!.Reports.Single(q=>q.Id==delivered.Id).Observation!.ObservedAt<s.Seconds);Assert.Null(s.CommunityEconomyView());}
    [Fact]public void FixedReportAddressDoesNotTrackAbsentPrincipal(){var s=Start(true);var g=Grant(s,new("site:castle"));Good(Act(s,StewardAction.Report,g));var report=s.DiagnosticSnapshot().Stewardship!.Papers.Single();Advance(s,10*86400);Assert.Equal(new EntityId("site:castle"),report.Address);Assert.DoesNotContain(s.DiagnosticSnapshot().Messaging.Attempts,a=>a.MessageId==report.Id&&a.Status==AttemptStatus.Delivered);Assert.Equal(3000,report.Observation!.Accounts.HouseRice);}
    [Fact]public void SharedIdCannotBecomeAnotherRequestType(){var s=Start(true);var g=Grant(s);Assert.Equal(ResultCode.IdPayloadConflict,s.ManageCommunity(new(g,Site,EconomyAction.RelieveVillage,1),s.PlayerControl,s.Revision).Code);Assert.Equal(ResultCode.IdPayloadConflict,s.Submit(TravelWorld.Move(s.DiagnosticSnapshot(),g.Value,"castle"),s.Revision).Code);}
    [Fact]public void ReservedSalaryCannotBeSpentByGrantedAgent(){var s=Start(true);Good(s.ManageSalary(new(new("request:salary-offer"),SalaryAction.Propose,Head,Site,Amount:40),s.PlayerControl,s.Revision));var salary=s.DiagnosticSnapshot().Salary!.Quotes.Single().Id;Good(s.ManageSalary(new(new("request:salary-confirm"),SalaryAction.Confirm,Head,Site,salary),s.PlayerControl,s.Revision));Advance(s,31*86400);var g=Grant(s);Good(s.ManageSalary(new(new("request:salary-ready"),SalaryAction.Prepare,Head,Site,salary,40),s.PlayerControl,s.Revision));for(int n=0;n<5;n++)Good(Act(s,StewardAction.Operate,g,EconomyAction.RelieveVillage,100));Assert.True(A(s).HouseRice>=40);Assert.Equal(40,s.SalaryView()!.Contracts.Single().Prepared);}
    [Fact]public void ManualReportCopiesAreBoundedAndNeverUpdateObservation(){var s=Start(true);var g=Grant(s);Good(Act(s,StewardAction.Report,g));var p=s.DiagnosticSnapshot().Stewardship!.Papers.Single();Good(Act(s,StewardAction.ResendReport,g,report:p.Id));Good(Act(s,StewardAction.ResendReport,g,report:p.Id));Assert.Equal(ResultCode.NotAvailable,Act(s,StewardAction.ResendReport,g,report:p.Id).Code);Assert.Equal(3,s.DiagnosticSnapshot().Stewardship!.Papers.Length);Assert.All(s.DiagnosticSnapshot().Stewardship!.Papers,q=>Assert.Equal(p.Observation,q.Observation));}
}
